import{_ as o,C as a,o as s,c as n,ag as r,E as i}from"./chunks/framework.CtWPcAmt.js";const b=JSON.parse('{"title":"Manage Pricing","description":"","frontmatter":{},"headers":[],"relativePath":"pricing/manage-pricing.md","filePath":"pricing/manage-pricing.md","lastUpdated":1786088921000}'),c={name:"pricing/manage-pricing.md"};function l(g,e,p,d,u,h){const t=a("ImagePopup");return s(),n("div",null,[e[0]||(e[0]=r('<h1 id="manage-pricing" tabindex="-1">Manage Pricing <a class="header-anchor" href="#manage-pricing" aria-label="Permalink to &quot;Manage Pricing&quot;">​</a></h1><p>Manage Pricing is where a seller controls prices across their whole catalog from one screen — base price, scheduled sale prices, and customer-group tiers — with bulk tools to reprice many products at once.</p><div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>What you can edit on the pricing screen</li><li>How to set a scheduled sale price</li><li>How to build customer-group price tiers and bulk-reprice</li></ul></div><h2 id="the-pricing-screen" tabindex="-1">The pricing screen <a class="header-anchor" href="#the-pricing-screen" aria-label="Permalink to &quot;The pricing screen&quot;">​</a></h2><p>Open <strong>Pricing</strong> in the Seller Panel. Each row is a product (simple and virtual) with inline fields for its <strong>price</strong>, <strong>sale price</strong>, and the sale&#39;s <strong>valid-from / valid-to</strong> dates. You can <strong>search</strong>, <strong>filter</strong> by category or type, and edit directly in the row.</p>',5)),i(t,{src:"/images/manage-pricing/pricing.png",alt:"Manage Pricing screen"}),e[1]||(e[1]=r('<h2 id="sale-prices" tabindex="-1">Sale prices <a class="header-anchor" href="#sale-prices" aria-label="Permalink to &quot;Sale prices&quot;">​</a></h2><p>Set a <strong>Sale price</strong> and a <strong>Valid from / Valid to</strong> window on a product, and the reduced price shows on the storefront automatically during that period. This is the quickest way to run a simple, scheduled price cut — for rule-based or cart-wide promotions, use <a href="/marketing/product-discounts">Product Discounts</a> and <a href="/marketing/checkout-deals">Checkout Deals</a> instead.</p><h2 id="customer-group-price-tiers" tabindex="-1">Customer-group price tiers <a class="header-anchor" href="#customer-group-price-tiers" aria-label="Permalink to &quot;Customer-group price tiers&quot;">​</a></h2><p>For products you <strong>own</strong>, you can add <strong>advanced pricing tiers</strong> — special prices for specific customer groups and quantities. Each tier sets a <strong>Group</strong> (all groups or a specific one), a <strong>Qty</strong>, a <strong>Type</strong> (<strong>fixed</strong> price or <strong>discount</strong>), and a <strong>Value</strong>. Add as many tiers as you need, or remove them.</p><h2 id="bulk-repricing" tabindex="-1">Bulk repricing <a class="header-anchor" href="#bulk-repricing" aria-label="Permalink to &quot;Bulk repricing&quot;">​</a></h2><p>Select several products and use the <strong>bulk price tool</strong>: choose an <strong>action</strong> (<strong>set</strong>, <strong>increase</strong>, or <strong>decrease</strong>), a <strong>mode</strong> (by <strong>amount</strong> or <strong>percent</strong>), and a value, then <strong>Apply</strong>. A save bar at the bottom tracks changes; <strong>Save</strong> writes them all at once.</p><div class="info custom-block"><p class="custom-block-title">Reselling vs owning</p><p>For products you <strong>resell</strong> (assigned), you set only the flat <strong>price</strong> — sale prices and customer-group tiers apply to products you own.</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Combine a bulk <strong>decrease</strong> by percent with a sale-price window to run a catalog-wide sale, then bulk <strong>increase</strong> back afterwards — all from this one screen.</p></div>',8))])}const _=o(c,[["render",l]]);export{b as __pageData,_ as default};
